//! Replays the golden corpus generated by
//! `electricity/scripts/generate_stdlib_tools_corpus.py` -- real output
//! from Circuitry's own `FsPlugin`/`EnvVarsPlugin`/`HashPlugin`/
//! `UuidPlugin.execute` (`plugins/{fs,env_vars,hash,uuid}.py`) -- against
//! this crate's own ports.
//!
//! `<root>` in a case's own recorded strings is the generating machine's
//! own temp directory, replaced before the corpus was committed; this
//! test substitutes *this* machine's own fresh temp directory for it
//! before running, in both directions (into the params fed to the
//! plugin, and back out of the expected strings compared against).
//!
//! The corpus is checked in (`tests/golden/stdlib_tools_corpus.json`); CI
//! separately regenerates it with Python 3.11 and fails the build if it
//! differs (`.github/workflows/electricity-generated.yml`), so this test
//! only needs to trust the committed file.
//!
//! Everything here runs in one `#[test]` function, deliberately not
//! split into several `#[tokio::test]`s: the `env_vars` cases replace
//! the whole process environment for the length of their own section
//! (`mock.patch.dict(os.environ, ..., clear=True)`'s own Rust
//! equivalent -- there is no atomic "clear" in `std::env`, only
//! `remove_var` per name) and restore it immediately afterward; a
//! second test in this same binary running concurrently on another
//! thread could otherwise observe -- or stomp on -- that window.

use chrono::{DateTime, TimeZone, Utc};
use electricity_tools::clock::execute_at;
use electricity_tools::{
    ToolCall, ToolPlugin, env_vars::EnvVarsPlugin, fs::FsPlugin, hash::HashPlugin, uuid::UuidPlugin,
};
use electricity_value::{CancellationToken, Dict, IntValue, Value};
use serde::Deserialize;
use std::path::PathBuf;

#[derive(Deserialize, Debug, Clone)]
#[serde(tag = "t")]
enum TaggedValue {
    #[serde(rename = "none")]
    None,
    #[serde(rename = "bool")]
    Bool { v: bool },
    #[serde(rename = "int")]
    Int { v: String },
    #[serde(rename = "float")]
    Float { bits: String },
    #[serde(rename = "str")]
    Str { v: String },
    #[serde(rename = "list")]
    List { v: Vec<TaggedValue> },
    #[serde(rename = "dict")]
    Dict { v: Vec<(TaggedValue, TaggedValue)> },
}

impl From<TaggedValue> for Value {
    fn from(tagged: TaggedValue) -> Self {
        match tagged {
            TaggedValue::None => Value::None,
            TaggedValue::Bool { v } => Value::Bool(v),
            TaggedValue::Int { v } => {
                Value::Int(IntValue::parse_decimal(&v).expect("valid decimal integer"))
            }
            TaggedValue::Float { bits } => {
                let bits = u64::from_str_radix(&bits, 16).expect("valid hex bit pattern");
                Value::Float(f64::from_bits(bits))
            }
            TaggedValue::Str { v } => Value::Str(v),
            TaggedValue::List { v } => Value::List(v.into_iter().map(Value::from).collect()),
            TaggedValue::Dict { v } => {
                let mut dict = Dict::new();
                for (k, val) in v {
                    dict.insert(Value::from(k), Value::from(val));
                }
                Value::Dict(dict)
            }
        }
    }
}

/// Replaces `<root>` with *root* in every string leaf of a decoded
/// [`TaggedValue`] -- the reverse of the generator's own redaction.
fn substitute_root(tagged: TaggedValue, root: &str) -> TaggedValue {
    match tagged {
        TaggedValue::Str { v } => TaggedValue::Str {
            v: v.replace("<root>", root),
        },
        TaggedValue::List { v } => TaggedValue::List {
            v: v.into_iter().map(|t| substitute_root(t, root)).collect(),
        },
        TaggedValue::Dict { v } => TaggedValue::Dict {
            v: v.into_iter()
                .map(|(k, val)| (substitute_root(k, root), substitute_root(val, root)))
                .collect(),
        },
        other => other,
    }
}

#[derive(Deserialize)]
struct GenericCase {
    case: String,
    params: TaggedValue,
    ok: Option<TaggedValue>,
    raw: Option<TaggedValue>,
    err: Option<String>,
}

/// `clock` cases carry their own frozen instant (whole seconds since
/// the epoch, plus a microseconds remainder) -- there's no shared
/// `ToolPlugin::execute` call this replay can drive the way the other
/// four tools' [`GenericCase`]s do, since `clock`'s own entry point
/// takes *now* as an explicit parameter ([`execute_at`]).
#[derive(Deserialize)]
struct ClockCase {
    case: String,
    params: TaggedValue,
    epoch_seconds: i64,
    epoch_micros: u32,
    ok: Option<TaggedValue>,
    raw: Option<TaggedValue>,
    err: Option<String>,
}

#[derive(Deserialize)]
struct Corpus {
    fs_cases: Vec<GenericCase>,
    env_vars_cases: Vec<GenericCase>,
    hash_cases: Vec<GenericCase>,
    uuid_cases: Vec<GenericCase>,
    clock_cases: Vec<ClockCase>,
}

fn call<'a>(token: &'a CancellationToken, config: &'a Value) -> ToolCall<'a> {
    ToolCall {
        timeout_seconds: 30,
        config,
        token,
        armed: false,
    }
}

async fn run_case(
    plugin: &dyn ToolPlugin,
    case: GenericCase,
    root: &str,
    failures: &mut Vec<String>,
) {
    let name = plugin.name().to_string();
    let params = Value::from(substitute_root(case.params, root));
    let token = CancellationToken::new();
    let none_config = Value::None;
    let got = plugin
        .execute(params.clone(), &call(&token, &none_config))
        .await;
    match (got, case.ok, case.raw, case.err) {
        (Ok(got), Some(ok), Some(raw), None) => {
            let expected_value = Value::from(substitute_root(ok, root));
            let expected_raw = Value::from(substitute_root(raw, root));
            if got.value != expected_value || got.raw != expected_raw {
                failures.push(format!(
                    "{name}/{}: expected value={expected_value:?} raw={expected_raw:?}, got value={:?} raw={:?}",
                    case.case, got.value, got.raw
                ));
            }
        }
        (Err(err), None, None, Some(expected)) => {
            let expected = expected.replace("<root>", root);
            if err.message != expected {
                failures.push(format!(
                    "{name}/{}: expected err {expected:?}, got {:?}",
                    case.case, err.message
                ));
            }
        }
        (got, expected_ok, expected_raw, expected_err) => failures.push(format!(
            "{name}/{}: expected ok={expected_ok:?} raw={expected_raw:?} err={expected_err:?}, got {:?}",
            case.case,
            got.map(|r| (r.value, r.raw))
        )),
    }
}

fn temp_root(tag: &str) -> PathBuf {
    let dir = std::env::temp_dir().join(format!(
        "electricity-stdlib-tools-corpus-replay-{tag}-{}",
        std::process::id()
    ));
    std::fs::create_dir_all(&dir).unwrap();
    std::fs::canonicalize(&dir).unwrap()
}

#[tokio::test(flavor = "current_thread")]
async fn golden_corpus_stdlib_tools() {
    let text = include_str!("golden/stdlib_tools_corpus.json");
    let corpus: Corpus =
        serde_json::from_str(text).expect("golden/stdlib_tools_corpus.json is valid JSON");
    let mut failures = Vec::new();

    // --- fs ---
    let fs_root = temp_root("fs");
    // The corpus's own `crlf.txt`/`sub/{a,b,c}.txt` fixtures are written
    // directly by the generator (never through the plugin itself), so
    // this replay has to recreate them the same way before any case
    // that reads them runs.
    std::fs::write(fs_root.join("crlf.txt"), b"a\r\nb\rc\n").unwrap();
    std::fs::create_dir_all(fs_root.join("sub")).unwrap();
    for name in ["b.txt", "a.txt", "c.txt"] {
        std::fs::write(fs_root.join("sub").join(name), b"").unwrap();
    }
    assert!(!corpus.fs_cases.is_empty());
    let root_str = fs_root.to_str().unwrap().to_string();
    for case in corpus.fs_cases {
        run_case(&FsPlugin, case, &root_str, &mut failures).await;
    }
    std::fs::remove_dir_all(&fs_root).ok();

    // --- hash ---
    let hash_root = temp_root("hash");
    std::fs::write(hash_root.join("hash_input.bin"), b"hello from a file").unwrap();
    let hash_root_str = hash_root.to_str().unwrap().to_string();
    assert!(!corpus.hash_cases.is_empty());
    for case in corpus.hash_cases {
        run_case(&HashPlugin, case, &hash_root_str, &mut failures).await;
    }
    std::fs::remove_dir_all(&hash_root).ok();

    // --- uuid ---
    assert!(!corpus.uuid_cases.is_empty());
    for case in corpus.uuid_cases {
        run_case(&UuidPlugin, case, "", &mut failures).await;
    }

    // --- env_vars: a fully replaced process environment for the
    // length of this block only, matching the generator's own
    // `mock.patch.dict(os.environ, ..., clear=True)`.
    assert!(!corpus.env_vars_cases.is_empty());
    let saved: Vec<(String, String)> = std::env::vars().collect();
    for (name, _) in &saved {
        unsafe { std::env::remove_var(name) };
    }
    for (name, value) in [
        ("PATH", "/usr/bin:/bin"),
        ("HOME", "/home/fake"),
        ("MY_API_KEY_SUFFIX", "visible-name-but-masked-value"),
        ("MY_APIKEYLESS_VAR", "also-masked"),
        ("PLAIN_VAR", "plain-value"),
        ("APP_PREFIXED_ONE", "one"),
        ("APP_PREFIXED_TWO", "two"),
    ] {
        unsafe { std::env::set_var(name, value) };
    }
    for case in corpus.env_vars_cases {
        run_case(&EnvVarsPlugin, case, "", &mut failures).await;
    }
    for (name, _) in std::env::vars().collect::<Vec<_>>() {
        unsafe { std::env::remove_var(&name) };
    }
    for (name, value) in &saved {
        unsafe { std::env::set_var(name, value) };
    }

    // --- clock: each case carries its own frozen instant (there's no
    // shared process environment or filesystem state to set up/tear
    // down the way the other sections need).
    assert!(!corpus.clock_cases.is_empty());
    for case in corpus.clock_cases {
        let now: DateTime<Utc> = Utc
            .timestamp_opt(case.epoch_seconds, case.epoch_micros * 1000)
            .single()
            .expect("valid recorded instant");
        let params = Value::from(case.params);
        let got = execute_at(&params, now);
        match (got, case.ok, case.raw, case.err) {
            (Ok(got), Some(ok), Some(raw), None) => {
                let expected_value = Value::from(ok);
                let expected_raw = Value::from(raw);
                if got.value != expected_value || got.raw != expected_raw {
                    failures.push(format!(
                        "clock/{}: expected value={expected_value:?} raw={expected_raw:?}, got value={:?} raw={:?}",
                        case.case, got.value, got.raw
                    ));
                }
            }
            (Err(err), None, None, Some(expected)) => {
                if err.message != expected {
                    failures.push(format!(
                        "clock/{}: expected err {expected:?}, got {:?}",
                        case.case, err.message
                    ));
                }
            }
            (got, expected_ok, expected_raw, expected_err) => failures.push(format!(
                "clock/{}: expected ok={expected_ok:?} raw={expected_raw:?} err={expected_err:?}, got {:?}",
                case.case,
                got.map(|r| (r.value, r.raw))
            )),
        }
    }

    assert!(failures.is_empty(), "{}", failures.join("\n"));
}
